"""Build the curated source manifest (one row per source) from the raw download log and the audit's inspection notes."""
import sys
from pathlib import Path

import pandas as pd

sys.stdout.reconfigure(encoding="utf-8")
A = Path(sys.argv[1])
raw = pd.read_csv(A / "source_manifest_raw.csv")
raw.to_csv(A / "source_manifest_files.csv", index=False)  # every request: URL, time, status, bytes, SHA-256, local file

