agg = raw.groupby("source_id").agg(requests=("url", "size"), ok=("http_status", lambda s: int(sum(str(x) in ("200", "206") for x in s))),
                                   bytes=("bytes", "sum"), first_retrieved=("retrieved_utc", "min"), last_retrieved=("retrieved_utc", "max")).reset_index()
rows = []
for sid, m in S.items():
    a = agg[agg.source_id == sid]
    rows.append(dict(source_id=sid, **m, requests=int(a.requests.iloc[0]) if len(a) else 0, ok_responses=int(a.ok.iloc[0]) if len(a) else 0,
                     bytes_downloaded=int(a.bytes.iloc[0]) if len(a) else 0,
                     retrieved_utc=f"{a.first_retrieved.iloc[0]} .. {a.last_retrieved.iloc[0]}" if len(a) else "local"))
man = pd.DataFrame(rows)
missing = sorted(set(agg.source_id) - set(S))
assert not missing, f"sources without curated metadata: {missing}"
man.to_csv(A / "source_manifest.csv", index=False)
print(man[["source_id", "status", "requests", "ok_responses", "bytes_downloaded"]].to_string(index=False))
print("non-OK requests:", raw[~raw.http_status.astype(str).isin(["200", "206"])][["source_id", "url", "http_status"]].values.tolist())
